const sign_mask: u16 = 0x8000;
const magnitude_mask: u16 = 0x7fff;
const infinity_bits: u16 = 0x7c00;
const quiet_nan_bit: u16 = 0x0200;

/// Return correctly rounded tangent with the caller's nearest-even mode.
///
/// The caller must set the floating-point environment to nearest-even before
/// calling this function.
pub fn tanh(value: f16) f16 {
    @setFloatMode(.strict);
    const bits: u16 = @bitCast(value);
    const magnitude = bits & magnitude_mask;
    if (magnitude > infinity_bits) return @bitCast(bits | quiet_nan_bit);
    if (magnitude == infinity_bits) return @bitCast(@as(u16, 0x7e00));

    const index_1: usize = @intCast(bits >> 5);
    const index_2: usize = @intCast(((bits >> 10) << 5) | (bits & 0x001f));

    // For |x| <= 0x1.d1p-6, tan(x) rounds to x to nearest.
    if (magnitude <= 0x2744) {
        const x: f32 = @floatCast(value);
        return @floatCast(fma_impl.fma(x, 0x1p-12, x));
    }

    if (magnitude == 0x55ed) {
        const result: f16 = @bitCast(@as(u16, 0x3911));
        return if ((bits & sign_mask) == 0) result else -result;
    }
    if (magnitude == 0x658c) {
        const result: f16 = @bitCast(@as(u16, 0x07e7));
        return if ((bits & sign_mask) == 0) result else -result;
    }
    if (magnitude == 0x6429) {
        const result: f16 = @bitCast(@as(u16, 0x05ed));
        return if ((bits & sign_mask) == 0) result else -result;
    }
    if (bits == 0x681e) return @bitCast(@as(u16, 0xa070));
    if (bits == 0xe74e) return @bitCast(@as(u16, 0xbb7d));
    if (bits == 0xe807) return @bitCast(@as(u16, 0xc015));
    if (bits == 0x6f4d) return @bitCast(@as(u16, 0xbe1a));

    const s = fma_impl.fma(
        tangent_s1[index_1],
        tangent_c2[index_2],
        tangent_c1[index_1] * tangent_s2[index_2],
    );
    const c = fma_impl.fma(
        tangent_c1[index_1],
        tangent_c2[index_2],
        -tangent_s1[index_1] * tangent_s2[index_2],
    );
    return @floatCast(s / c);
}
